// Extract blog post links from Oracle blog HTML
const html = $input.first().json.data;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

const posts = [];
const baseUrl = 'https://blogs.oracle.com';

// Find blog post links (Oracle blog structure)
$('a[href*="/20"]').each((i, element) => {
  const href = $(element).attr('href');
  const title = $(element).text().trim();

  if (href && title && href.includes('/202')) {
    const fullUrl = href.startsWith('http') ? href : baseUrl + href;

    // Filter for infrastructure-related keywords
    const keywords = ['infrastructure', 'network', 'compute', 'storage', 'database', 
                     'mysql', 'mds', 'heatwave', 'vm', 'virtual machine', 'vcn',
                     'subnet', 'load balancer', 'security', 'backup', 'performance',
                     'kubernetes', 'container', 'terraform', 'automation', 'devops'];

    const titleLower = title.toLowerCase();
    const hasKeyword = keywords.some(keyword => titleLower.includes(keyword));

    if (hasKeyword && posts.length < 3) { // Limit to 3 posts per run for DeepAI quotas
      posts.push({
        url: fullUrl,
        title: title,
        relevance: 'high'
      });
    }
  }
});

return posts.map(post => ({ json: post }));

// Parse individual blog post content
const html = $input.first().json.data;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

// Extract title
let title = $('h1').first().text().trim();
if (!title) {
  title = $('title').text().trim();
}

// Extract content
let content = '';
const contentSelectors = ['.entry-content', 'article', '#content', '.post-content'];
for (const selector of contentSelectors) {
  const elem = $(selector);
  if (elem.length > 0) {
    content = elem.text().trim();
    break;
  }
}

// Extract author
let author = $('.author').first().text().trim();
if (!author) {
  author = $('[class*="author"]').first().text().trim() || 'Oracle Team';
}

// Extract date
let publishDate = $('time').attr('datetime') || new Date().toISOString().split('T')[0];

// Calculate content metrics
const wordCount = content.split(/\s+/).length;
const readingTime = Math.ceil(wordCount / 200); // 200 WPM average

// Truncate content for DeepAI processing (3000 chars limit)
const truncatedContent = content.substring(0, 3000);

return [{
  json: {
    original_url: $('input').item(0).json.url,
    title: title,
    content: truncatedContent,
    full_content: content,
    author: author,
    published_date: publishDate,
    word_count: wordCount,
    reading_time: readingTime,
    scraped_at: new Date().toISOString()
  }
}];

// Process DeepAI response and prepare article data
const deepAiResponse = $input.first().json;
const originalData = $('parse-blog-content').item(0).json;

let generatedContent = '';
let title = '';

// Extract content from DeepAI response
if (deepAiResponse.output) {
  generatedContent = deepAiResponse.output;

  // Extract title if it's in the content (usually first line)
  const lines = generatedContent.split('\n');
  const firstLine = lines[0].trim();

  // Check if first line looks like a title
  if (firstLine.length > 10 && firstLine.length < 100 && !firstLine.includes('.')) {
    title = firstLine.replace(/^#+\s*/, ''); // Remove markdown headers
    generatedContent = lines.slice(1).join('\n').trim();
  } else {
    // Generate title from original
    title = `Startup Guide: ${originalData.title.replace(/Oracle|OCI/gi, 'Cloud Infrastructure')}`;
  }
} else {
  // Fallback if DeepAI fails
  title = `Startup Infrastructure Guide: ${originalData.title}`;
  generatedContent = `This article covers ${originalData.title} from a startup perspective. Content generation in progress...`;
}

// Generate slug from title
const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 50);

// Calculate metrics
const wordCount = generatedContent.split(/\s+/).length;
const readabilityScore = Math.random() * 0.3 + 0.7; // Placeholder
const seoScore = Math.random() * 0.2 + 0.8; // Placeholder

// Create excerpt
const excerpt = generatedContent.substring(0, 200).trim() + '...';

// Keywords for startups + infrastructure
const keywords = [
  'startup cloud infrastructure',
  'Oracle Cloud for startups', 
  'network architecture',
  'cloud infrastructure startup',
  'OCI for growing business',
  'DMCloudArchitect'
];

return [{
  json: {
    title: title,
    slug: slug,
    content: generatedContent,
    excerpt: excerpt,
    keywords: JSON.stringify(keywords),
    word_count: wordCount,
    readability_score: readabilityScore,
    seo_score: seoScore,
    status: 'draft',
    created_at: new Date().toISOString(),
    original_source: originalData.original_url,
    deepai_response_id: deepAiResponse.id || 'unknown'
  }
}];

// Process DeepAI image response
const imageResponse = $input.first().json;
const articleData = $('process-deepai-content').item(0).json;

let imageUrl = '';
let altText = articleData.title;
let promptUsed = `Professional business illustration: ${articleData.title}`;

if (imageResponse.output_url) {
  imageUrl = imageResponse.output_url;
} else {
  // Fallback if image generation fails
  imageUrl = 'https://via.placeholder.com/1200x630/0066cc/ffffff?text=DMCloudArchitect';
}

return [{
  json: {
    article_id: null, // Will be updated after database insert
    prompt_used: promptUsed,
    image_url: imageUrl,
    image_type: 'featured',
    alt_text: altText,
    deepai_image_id: imageResponse.id || 'unknown',
    created_at: new Date().toISOString()
  }
}];

// Prepare Facebook post content
const articleData = $('process-deepai-content').item(0).json;
const imageData = $('process-image-response').item(0).json;

// Create engaging Facebook post
const postText = `🚀 New Startup Infrastructure Guide!

${articleData.title}

${articleData.excerpt}

💡 Key insights for startup founders:
✅ Practical Oracle Cloud solutions
✅ Cost-effective network architecture
✅ Scalable infrastructure planning

#StartupInfrastructure #OracleCloud #CloudArchitecture #DMCloudArchitect #TechStartups #Infrastructure

Read the full guide: [Link will be added when published]`;

// Prepare Facebook API payload
return [{
  json: {
    message: postText,
    link: '', // Will add blog URL when published
    picture: imageData.image_url,
    name: articleData.title,
    caption: 'DMCloudArchitect - Oracle Cloud Infrastructure for Startups',
    description: articleData.excerpt,
    article_id: $('save-to-database').item(0).json.insertId
  }
}];

